export function createAdaptive(storage){
 let state={skill:2,samples:[],reviewed:0,reason:'Learning your pace. Review six decisions to adjust the challenge.'};const seen=new Set();
 try{const saved=JSON.parse(storage.getItem('bloom-adaptive-v1')||'null');if(saved&&Number.isInteger(saved.skill)&&saved.skill>=0&&saved.skill<=20&&Number.isInteger(saved.reviewed)&&saved.reviewed>=0)state={...state,skill:saved.skill,reviewed:saved.reviewed};}catch{}
 const save=()=>{try{storage.setItem('bloom-adaptive-v1',JSON.stringify({skill:state.skill,reviewed:state.reviewed}));}catch{}};
 return {get:()=>({...state,samples:state.samples.length}),reset(){seen.clear();state={skill:2,samples:[],reviewed:0,reason:'Fresh start. Learning your pace over six decisions.'};save();},record({key,loss,assisted=false}){if(!Number.isFinite(loss)||seen.has(key))return;seen.add(key);state.reviewed++;state.samples.push({loss:Math.max(0,Math.min(loss,1000)),assisted});if(state.samples.length===6){const average=state.samples.reduce((sum,s)=>sum+s.loss,0)/6;const old=state.skill;if(average>=150)state.skill=Math.max(0,state.skill-2);else if(average<=50&&!state.samples.some(s=>s.assisted))state.skill=Math.min(20,state.skill+1);state.reason=state.skill>old?'Your recent decisions held up well. Challenge increased one step.':state.skill<old?'Recent decisions were harder. Giving you more room to practice.':'Keeping this challenge while you build consistency.';state.samples=[];}save();}};
}
